import sys
import os
import csv
import json
import datetime
from decimal import Decimal

FACT_MAPPING = {
    "offered wage": ("lca_disclosure", "WAGE_RATE_OF_PAY_FROM", "amount"),
    "prevailing wage": ("lca_disclosure", "PREVAILING_WAGE", "amount"),
    "begin date": ("lca_disclosure", "BEGIN_DATE", "date"),
    "end date": ("lca_disclosure", "END_DATE", "date"),
}

def clean_amount(s):
    s = s.strip().replace('$', '').replace(',', '')
    if not s:
        return None
    d = Decimal(s)
    if d == d.to_integral():
        return str(int(d))
    else:
        return f"{d:f}".rstrip('0').rstrip('.')

def clean_date(s):
    s = s.strip()
    if not s:
        return None
    try:
        val = float(s)
        base_date = datetime.date(1899, 12, 30)
        dt = base_date + datetime.timedelta(days=int(val))
        return dt.strftime('%Y-%m-%d')
    except ValueError:
        pass

    for fmt in ('%Y-%m-%d', '%m/%d/%Y', '%d/%m/%Y', '%Y/%m/%d', '%B %d, %Y', '%b %d, %Y'):
        try:
            dt = datetime.datetime.strptime(s, fmt).date()
            return dt.strftime('%Y-%m-%d')
        except ValueError:
            pass
    return s

def clean_value(val, val_type):
    if val is None:
        return None
    val_str = str(val).strip()
    if not val_str:
        return None
    if val_type == "amount":
        return clean_amount(val_str)
    elif val_type == "date":
        return clean_date(val_str)
    return val_str

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load lca_disclosure records
    records_by_case = {}
    csv_filename = None
    for fname in os.listdir(packet_dir):
        if fname.lower() == "lca_disclosure.csv":
            csv_filename = os.path.join(packet_dir, fname)
            break

    if csv_filename and os.path.exists(csv_filename):
        with open(csv_filename, 'r', encoding='utf-8', errors='replace') as f:
            reader = csv.DictReader(f)
            for row in reader:
                cleaned_row = {k.strip(): v.strip() for k, v in row.items() if k is not None and v is not None}
                case_no = cleaned_row.get("CASE_NUMBER", "")
                if case_no:
                    if case_no not in records_by_case:
                        records_by_case[case_no] = []
                    records_by_case[case_no].append(cleaned_row)

    output = {}
    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_spec.get(rule_id, [])

        pair_result = {}
        entity_rows = records_by_case.get(entity, [])

        for fact_name in fact_names:
            if fact_name not in FACT_MAPPING:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, col_name, val_type = FACT_MAPPING[fact_name]

            values = set()
            for row in entity_rows:
                raw_val = row.get(col_name)
                cleaned = clean_value(raw_val, val_type)
                if cleaned:
                    values.add(cleaned)

            if len(values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(values) == 1:
                val = next(iter(values))
                pair_result[fact_name] = [val, doc_name]
            else:
                pair_result[fact_name] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=1))

if __name__ == "__main__":
    main()

