import sys
import os
import csv
import json
import datetime


def parse_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val or val.lower() in ("nan", "none", "null", "nat", ""):
        return None

    # Try numeric (Excel serial date)
    try:
        f = float(val)
        if 10000 <= f <= 100000:
            d = datetime.date(1899, 12, 30) + datetime.timedelta(days=int(round(f)))
            return d.strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Try common string date formats
    for fmt in (
        "%Y-%m-%d",
        "%m/%d/%Y",
        "%d/%m/%Y",
        "%Y/%m/%d",
        "%m-%d-%Y",
        "%d-%m-%Y",
        "%Y%m%d",
        "%B %d, %Y",
        "%b %d, %Y",
        "%b. %d, %Y",
        "%d %B %Y",
        "%d %b %Y",
    ):
        try:
            dt = datetime.datetime.strptime(val, fmt)
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            pass

    return val


def parse_amount(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val or val.lower() in ("nan", "none", "null", ""):
        return None
    v = val.replace("$", "").replace(",", "").strip()
    if not v:
        return None
    return v


def extract_fact_value(fact_name, row):
    k = fact_name.lower().strip()
    if k == "offered wage":
        raw = row.get("WAGE_RATE_OF_PAY_FROM")
        return parse_amount(raw)
    elif k == "prevailing wage":
        raw = row.get("PREVAILING_WAGE")
        return parse_amount(raw)
    elif k == "begin date":
        raw = row.get("BEGIN_DATE")
        return parse_date(raw)
    elif k == "end date":
        raw = row.get("END_DATE")
        return parse_date(raw)
    else:
        # Fallback to direct column lookup if present
        col = k.replace(" ", "_").upper()
        raw = row.get(col)
        if "date" in k:
            return parse_date(raw)
        elif any(w in k for w in ("wage", "pay", "rate", "salary", "amount")):
            return parse_amount(raw)
        return str(raw).strip() if raw is not None and str(raw).strip() else None


def load_lca_disclosure(packet_dir):
    records = {}
    doc_name = "lca_disclosure"

    target_file = None
    for root, _, files in os.walk(packet_dir):
        for f in files:
            stem, ext = os.path.splitext(f)
            if stem.lower() == "lca_disclosure" and ext.lower() in (".csv", ".tsv", ".txt"):
                target_file = os.path.join(root, f)
                doc_name = stem
                break
        if target_file:
            break

    if not target_file:
        return records, doc_name

    with open(target_file, mode="r", encoding="utf-8-sig", errors="replace") as f:
        reader = csv.DictReader(f)
        for r in reader:
            row_upper = {k.upper().strip(): v for k, v in r.items() if k}
            case_num = row_upper.get("CASE_NUMBER")
            if case_num:
                case_num = case_num.strip()
                if case_num not in records:
                    records[case_num] = []
                records[case_num].append(row_upper)

    return records, doc_name


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, mode="r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    records, doc_name = load_lca_disclosure(packet_dir)

    results = {}
    for pair in pairs:
        if "::" in pair:
            rule_id, entity_id = pair.split("::", 1)
        else:
            rule_id, entity_id = pair, ""

        rule_facts = facts_spec.get(rule_id, [])
        pair_result = {}

        entity_rows = records.get(entity_id, [])

        for fact_name in rule_facts:
            if not entity_rows:
                pair_result[fact_name] = "ABSENT"
                continue

            values = set()
            for row in entity_rows:
                val = extract_fact_value(fact_name, row)
                if val is not None and val != "":
                    values.add(val)

            if len(values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact_name] = [list(values)[0], doc_name]
            else:
                pair_result[fact_name] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))


if __name__ == "__main__":
    main()

